CREATE TRANSIENT TABLE P_LEW_LOAD.T_TS_INVENTUR_2_INV_DIFF_RECORD_POS_2
(
  RECORD_ID           NUMBER(10,0)                  NULL,
  CLIENT_ID           NUMBER(38)                    NULL       COMMENT 'DWH-Mandant_2; FK auf CLIENT',
  RECORD_YEAR         NUMBER(38)                    NULL       COMMENT 'Belegjahr; SAP-BW: inventur.doc_year',
  RECORD_CD           VARCHAR(20) COLLATE 'en-ci'   NULL       COMMENT 'Belegnummer; SAP-BW: inventur.mat_doc',
  RECORD_POS_ID       NUMBER(38)                    NULL       COMMENT 'Belegposition; SAP-BW: inventur.mat_item',
  RECORD_POS_SUB_ID   NUMBER(38)                    NULL       COMMENT 'Belegsubposition; SAP-BW: inventur.zmbwcount',
  LOC_SID             NUMBER(38)                    NULL       COMMENT 'WH / Filiale; SAP-BW: inventur.plant',
  ITEM_SID            NUMBER(38)                    NULL       COMMENT 'Artikel_2; SAP-BW: inventur.material',
  COMP_SID            NUMBER(38)                    NULL       COMMENT 'Buchungskreis; FK auf COMPANY; SAP-BW: inventur.comp_code',
  SALES_ORG_SID       NUMBER(38)                    NULL       COMMENT 'Verkaufsorganisation; FK auf SALES_2 ORG; SAP-BW: inventur.salesorg',
  UOM_SID             NUMBER(38)                    NULL       COMMENT 'Mengeneinheit der Inventurdifferenz; FK auf lew_core.t_unit_of_measurement_2; SAP-BW: inventur.zustvarme',
  CURR_SID            NUMBER(38)                    NULL       COMMENT 'Belegwaehrung: Waehrung der bewerteten Inventurdifferenz; FK auf lew_core.t_currency_2; SAP-BW: inventur.doc_currcy',
  MOVE_TYPE_CD        VARCHAR(20)                   NULL       COMMENT 'Buchungsart (s. t_item_movement_record_pos_2); SAP-BW: inventur.movetyp',
  STORAGE_LOC_CD      VARCHAR(20) COLLATE 'en-ci'   NULL       COMMENT 'Lagerort innerhalb der Location_2; SAP-BW: inventur.stor_loc',
  INV_NR              VARCHAR(20) COLLATE 'en-ci'   NULL       COMMENT 'zugehoerige Inventurnummer (falls vorhanden); SAP-BW: inventur.zminvnu1',
  INV_RECORD_CD       VARCHAR(20) COLLATE 'en-ci'   NULL       COMMENT 'zugehoerige Inventurbelegnummer (falls vorhanden); SAP-BW: inventur.zmiblnr',
  INV_DT              DATE                          NULL       COMMENT 'zugehoeriges Inventurdatum; SAP-BW: inventur.zmdzldat',
  INV_TYPE_CD         VARCHAR(20) COLLATE 'en-ci'   NULL       COMMENT 'Inventurtyp (A=Vollinventur; B=Teilinventur; C=Gesellschaftsinitiierte Einzelinventur; D=Filialinitiierte Einzelinventur); SAP-BW: inventur.zmpidtype',
  UOM_CD              VARCHAR(20)                   NULL       COMMENT 'Mengeneinheit der Inventurdifferenz; SAP-BW: inventur.zustvarme',
  INV_DIFF_QTY        NUMBER(18,5)                  NULL       COMMENT 'Inventurdifferenz in Mengeneinheit uom_cd; SAP-BW: inventur.zaquantst',
  CURR_CD             VARCHAR(20)                   NULL       COMMENT 'Belegwaehrung: Waehrung der bewerteten Inventurdifferenz; SAP-BW: inventur.doc_currcy',
  INV_DIFF_GROSS_VAL  NUMBER(18,5)                  NULL       COMMENT 'Inventurdifferenz bewertet mit durchschnittlichem VK_2-Preis brutto; SAP-BW: inventur.zkibvalu',
  INV_DIFF_NET_VAL    NUMBER(18,5)                  NULL       COMMENT 'Inventurdifferenz bewertet mit durchschnittlichem VK_2-Preis netto; SAP-BW: inventur.zkinvalu',
  DWH_CAL_DT          DATE                          NULL       COMMENT 'Belegdatum; SAP-BW: inventur.calday',
  DWH_LOAD_ID         NUMBER(38)                    NULL       COMMENT 'Identifier des letzten Ladelaufs, der den Datensatz eingfuegt oder veraendert hat',
  DWH_CREATED         TIMESTAMP_NTZ(6)              NULL       COMMENT 'Zeitstempel der Ersteinfuegung des Datensatzes ins DWH',
  DWH_UPDATED         TIMESTAMP_NTZ(6)              NULL       COMMENT 'Zeitstempel der letzten Aenderung des Datensatzes im DWH',
  DWH_MAPPING_DT      DATE                          NULL,
  ERROR_FG            NUMBER(38)                    NULL,
  ERROR_DESCR         VARCHAR(1000) COLLATE 'en-ci' NULL,
  FILENAME            VARCHAR(1000) COLLATE 'en-ci' NULL,
  HIST_ROW_NO         NUMBER(38)                    NULL
);